<?php require 'header.php';$statuses=['Pending','Confirmed','Processing','Ready for Delivery','Out for Delivery','Completed','Cancelled'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';if($id&&in_array($status,$statuses,true))db()->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Order status updated.');header('Location: manage-orders.php');exit;}$q=trim($_GET['q']??'');$sql='SELECT o.*,c.full_name,c.phone,c.whatsapp,c.email,c.address FROM orders o JOIN customers c ON c.id=o.customer_id';$params=[];if($q!==''){$sql.=' WHERE o.order_number LIKE ? OR c.full_name LIKE ? OR c.phone LIKE ?';$params=["%$q%","%$q%","%$q%"];}$sql.=' ORDER BY o.created_at DESC';$s=db()->prepare($sql);$s->execute($params);$orders=$s->fetchAll();?><div class="admin-title"><p>SALES</p><h2>Manage orders</h2></div><form class="inline-form" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search order, customer or phone"><button class="save">Search</button></form><section class="admin-panel"><table><thead><tr><th>Order</th><th>Customer / delivery</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><strong><?=e($o['order_number'])?></strong><br><small><?=e($o['created_at'])?></small></td><td><?=e($o['full_name'])?><br><?=e($o['phone'])?> / <?=e($o['whatsapp'])?><br><?=e($o['address'])?></td><td><?=money($o['total'])?></td><td><?=e($o['payment_method'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach($statuses as $status):?><option <?=$o['status']===$status?'selected':''?>><?=$status?></option><?php endforeach?></select><button>Save</button></form></td></tr><?php endforeach?></tbody></table></section><?php require 'footer.php'; ?>
